// Every caller knows the directory layout, the file naming
// scheme, the encoding, and the create-before-write dance.
public class ReportWriter
{
    public void Write(
        string baseDir,
        string reportName,
        string contents,
        Encoding encoding)
    {
        var dir = Path.Combine(baseDir, "reports",
            DateTime.UtcNow.ToString("yyyy-MM"));
        Directory.CreateDirectory(dir);
        var path = Path.Combine(dir, reportName + ".txt");
        File.WriteAllText(path, contents, encoding);
    }
}

// A caller — carrying decisions that are none of its business:
var writer = new ReportWriter();
writer.Write("C:/data", "q3-summary", text, Encoding.UTF8);

modelExamples.after:
// The directory layout, naming scheme, and encoding are
// design decisions the store owns. Callers name a report
// and hand over text; nothing else to know.
public class ReportStore
{
    private static readonly Encoding TextEncoding = Encoding.UTF8;
    private readonly string _root;

    public ReportStore(string root) => _root = root;

    public void Save(string reportName, string contents)
    {
        var dir = Path.Combine(_root, "reports",
            DateTime.UtcNow.ToString("yyyy-MM"));
        Directory.CreateDirectory(dir);
        File.WriteAllText(
            PathFor(dir, reportName), contents, TextEncoding);
    }

    private static string PathFor(string dir, string name) =>
        Path.Combine(dir, name + ".txt");
}

// A caller now:
store.Save("q3-summary", text);

