modelExamples.after:
// The connection lifecycle is hidden: opened on demand,
// flushed and closed by the queue itself. One method,
// no ordering rules for the caller to get wrong.
public class JobQueue
{
    private readonly QueueSettings _settings;
    private Connection? _connection;

    public JobQueue(QueueSettings settings) =>
        _settings = settings;

    public void Enqueue(Job job)
    {
        _connection ??= Connection.Open(_settings);
        _connection.Send(job);
        _connection.Flush();
    }
}

// Every caller now:
queue.Enqueue(job);

modelExamples.before:
// Config leakage: retry policy decisions ride through
// every caller as parameters nobody upstream understands.
public class PriceClient
{
    public decimal GetPrice(
        string symbol,
        int maxRetries,
        int delayMs,
        bool useBackoff)
    {
        for (var attempt = 0; ; attempt++)
        {
            try { return FetchOnce(symbol); }
            catch (HttpRequestException) when (attempt < maxRetries)
            {
                var wait = useBackoff
                    ? delayMs * (attempt + 1)
                    : delayMs;
                Thread.Sleep(wait);
            }
        }
    }
}

// Callers guess at values they have no basis to choose:
var price = client.GetPrice("MSFT", 3, 200, true);

modelExamples.after:
// The retry policy is the client's own design decision,
// chosen once with a sensible default. The surface shrinks
// to the one thing callers actually know: the symbol.
public class PriceClient
{
    private const int MaxRetries = 3;
    private static readonly TimeSpan BaseDelay =
        TimeSpan.FromMilliseconds(200);

    public decimal GetPrice(string symbol)
    {
        for (var attempt = 0; ; attempt++)
        {
            try { return FetchOnce(symbol); }
            catch (HttpRequestException) when (attempt < MaxRetries)
            {
                Thread.Sleep(BaseDelay * (attempt + 1));
            }
        }
    }
}

// Callers state intent, not policy:
var price = client.GetPrice("MSFT");

